/* ── extras 문자열 → 객체 ── */
const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
/* 원문 장 → 개념 말풍선 글 (글 판 장·글 없는 장은 교사 한 줄(lead), 나머지는 원문 그대로 — 게이트 F 가 같은 규칙으로 되짚는다) */
function srcContent(sl) {
  if (sl.kind === 'recap') return sl.items.join('\n');
  if (sl.kind === 'stage') return [sl.text, sl.stage].filter(Boolean).join('\n');
  if (!sl.text && sl.extra) return sl.extra.join('\n');
  return sl.text || '';
}
const kContent = (sl) => kq(srcContent(sl));
/* 가려내기 문항 → 기본 문제 (126차: 원문 힌트의 「힌트:」 머리는 뗀다) */
function problemData(sl, title, body, icon, keep, h) {
  const d = { title, scenario: { icon: icon || '📖', body }, question: sl.t };
  const hint = kq(String(sl.hint || h || '글을 다시 읽어 봐요.').replace(/^힌트:\s*/, ''));
  if (sl.kind === 'pick') { d.options = sl.opts.map((t, i) => (i === sl.ci ? { text: t, correct: true } : { text: t })); d.note = '풀이: ' + hint + ' → **' + nm(sl.opts[sl.ci]) + '**'; }
  else if (sl.kind === 'collect') { const ch = (keep || sl.chips.map((_, i) => i)).map(i => sl.chips[i]); d.options = ch.map(c => (c.hit ? { text: c.t, correct: true } : { text: c.t })); d.multi = true; d.note = '풀이: ' + hint + ' → 알맞은 것 **' + ch.filter(c => c.hit).length + '개**'; }
  else if (sl.kind === 'match') { d.answer = sl.pairs.map(p => p[0] + ' ↔ ' + p[1]).join(' / '); d.note = '풀이: ' + hint; }
  return d;
}

const LESSONS = {};
const keys = Object.keys(T);
keys.forEach((key, idx) => {
  const t = T[key], s = SRC[key], n = idx + 1;
  const ex = extras(n, t.ex); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevExit = idx === 0 ? PREV_EXIT.map(x => ({ q: kq(x.q), a: kq(x.a) })) : T[keys[idx - 1]].exit; /* 4단원 마지막 출구 그대로(게이트 D 확인) */
  const slides = [];
  const add = (block, stage, data, sug, tn, src) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (src != null) sl.src = src; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: '지난 시간엔 무엇을 했나요?', content: t.review, items: prevExit.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? PREV_KEY : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, kids: t.mot.kids.map(([face, label]) => ({ face, label })), question: t.mot.q, img: 'assets/photo/korean/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach(([si, fig, tn, lead], i) => { const src = s.slides[si]; const own = kContent(src); add('concept', '전개', { fig, title: nm(src.t), content: src.kind === 'read' || !own ? lead : own }, csug[i], tn, si); });
  add('misconception', '전개', { title: '이런 생각을 조심해요', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach(([pi, body, icon, keep, h], i) => add('basic_problem', '기본문제', problemData(s.slides[pi], '기본 문제 ' + '①②③'[i], body, icon, keep, h), bsug[i], null, pi));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  const sm = s.slides[t.sumSrc]; /* 정리 줄 = 원문 recap 줄(「④ 정리」가 있는 차시는 그 장 · 없는 차시는 T 표 sumSrc 의 원문 recap — 게이트 F 가 같은 표로 되짚는다) */
  const smItems = sm.items.map(kq);
  add('summary', '정리', { title: '오늘 배운 것', points: smItems.concat(t.sum.story), arrows: t.sum.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0][0], '🔧 과정·기능 — ' + t.self[0][1], '💛 가치·태도 — ' + t.self[0][2]], prompts: [t.self[1]] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '다음 단원엔' : '다음 시간엔', preview: t.next[0] + '. ' + t.next[1], emoji: t.next[2] }, [id('c', 1)]);
  const [a, b] = s.covers;
  LESSONS[key] = {
    meta: { grade: 4, subject: '국어', term: 2, unit: UNIT, unit_title: UT, n: a, covers: a === b ? a + '차시' : a + (b - a === 1 ? '·' : '~') + b + '차시', title: t.title, goal: s.goal, std: t.std, duration_min: 40 * (b - a + 1), lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '곰이·펭이 마음 우체국 교실', live_url: LIVE + s.file, source: 'grade4/semester2/korean/' + DIR + '/' + s.file },
    slides, extras: ex
  };
});

